const set = (index: number, drafts: Draft[]): QuizQuestion[] => {
  const s = WORLD_16_QUIZ_SETS[index];
  return drafts.map((d, i) => ({ ...d, id: `w16q-set-${index + 1}-${i + 1}`, worldId: W, lessonId: s.lessonIds.at(-1)!, setId: s.id, topic: s.title, xp: XP[d.difficulty] }) as unknown as QuizQuestion);
};

